/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, parseReference, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readRecords() {
  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const records = readRecords()
  const output = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        output.push(normalize(parseReference(record)))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) throw new UriError('expected a base and a reference')
        const baseText = record.slice(0, spaceIdx)
        const refText = record.slice(spaceIdx + 1)
        const base = parseReference(baseText)
        if (base.scheme === null) throw new UriError('the base has no scheme')
        const ref = parseReference(refText)
        output.push(normalize(resolve(base, ref)))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(`line ${lineNo}: ${err.message}`)
      }
      throw err
    }
  }

  process.stdout.write(output.map((line) => line + '\n').join(''))
}

main()
